pub mod bridged_stats_state {

    pub use crate::builder_types::{Set, Unset, IsSet, IsUnset};
    #[allow(unused)]
    use ::core::marker::PhantomData;
    mod sealed {
        pub trait Sealed {}
    }
    /// State trait tracking which required fields have been set
    pub trait State: sealed::Sealed {
        type AsOf;
        type Downvotes;
        type Upvotes;
    }
    /// Empty state - all required fields are unset
    pub struct Empty(());
    impl sealed::Sealed for Empty {}
    impl State for Empty {
        type AsOf = Unset;
        type Downvotes = Unset;
        type Upvotes = Unset;
    }
    ///State transition - sets the `as_of` field to Set
    pub struct SetAsOf<St: State = Empty>(PhantomData<fn() -> St>);
    impl<St: State> sealed::Sealed for SetAsOf<St> {}
    impl<St: State> State for SetAsOf<St> {
        type AsOf = Set<members::as_of>;
        type Downvotes = St::Downvotes;
        type Upvotes = St::Upvotes;
    }
    ///State transition - sets the `downvotes` field to Set
    pub struct SetDownvotes<St: State = Empty>(PhantomData<fn() -> St>);
    impl<St: State> sealed::Sealed for SetDownvotes<St> {}
    impl<St: State> State for SetDownvotes<St> {
        type AsOf = St::AsOf;
        type Downvotes = Set<members::downvotes>;
        type Upvotes = St::Upvotes;
    }
    ///State transition - sets the `upvotes` field to Set
    pub struct SetUpvotes<St: State = Empty>(PhantomData<fn() -> St>);
    impl<St: State> sealed::Sealed for SetUpvotes<St> {}
    impl<St: State> State for SetUpvotes<St> {
        type AsOf = St::AsOf;
        type Downvotes = St::Downvotes;
        type Upvotes = Set<members::upvotes>;
    }
    /// Marker types for field names
    #[allow(non_camel_case_types)]
    pub mod members {
        ///Marker type for the `as_of` field
        pub struct as_of(());
        ///Marker type for the `downvotes` field
        pub struct downvotes(());
        ///Marker type for the `upvotes` field
        pub struct upvotes(());
    }
}

